use std::path::{Path, PathBuf};

pub fn gather(a: &str) -> Result<Vec<String>, i32> {
    let allowed = std::fs::canonicalize("/app/vatlogs").map_err(|_| 2)?;
    let root = std::fs::canonicalize(a).map_err(|_| 2)?;
    if !root.starts_with(&allowed) || !root.is_dir() {
        return Err(2);
    }
    let mut paths = Vec::new();
    visit(&root, &allowed, &mut paths)?;
    if paths.is_empty() {
        return Err(2);
    }
    paths.sort();
    Ok(paths.into_iter().map(|p| p.to_string_lossy().into_owned()).collect())
}

fn visit(dir: &Path, allowed: &Path, out: &mut Vec<PathBuf>) -> Result<(), i32> {
    let rd = std::fs::read_dir(dir).map_err(|_| 2)?;
    for entry in rd {
        let entry = entry.map_err(|_| 2)?;
        let original = entry.path();
        let path = std::fs::canonicalize(&original).map_err(|_| 2)?;
        if !path.starts_with(allowed) {
            return Err(2);
        }
        let meta = std::fs::metadata(&path).map_err(|_| 2)?;
        if meta.is_dir() {
            visit(&path, allowed, out)?;
        } else if meta.is_file() {
            out.push(path);
        } else {
            return Err(2);
        }
    }
    Ok(())
}
