pub fn take(text: &str) -> Result<(String, Vec<String>), i32> {
    if text.trim().is_empty() {
        return Err(3);
    }
    let mut kind: Option<String> = None;
    let mut frames = Vec::new();
    let mut expected_frame = 0usize;
    let mut summary = false;

    for line in text.lines() {
        if line.contains("ERROR:") {
            if kind.is_some() {
                return Err(3);
            }
            let after_error = line.split_once("ERROR:").ok_or(3)?.1.trim();
            let after = after_error
                .strip_prefix("AddressSanitizer:")
                .unwrap_or(after_error)
                .trim();
            let value = after.split(" on ").next().unwrap_or("").trim();
            if value.is_empty() {
                return Err(3);
            }
            kind = Some(value.to_string());
        }
        if line.trim_start().starts_with("SUMMARY:") {
            summary = true;
        }
        let t = line.trim_start();
        if let Some(rest) = t.strip_prefix('#') {
            let digits_len = rest.bytes().take_while(|b| b.is_ascii_digit()).count();
            if digits_len == 0 {
                return Err(3);
            }
            let n: usize = rest[..digits_len].parse().map_err(|_| 3)?;
            if n != expected_frame {
                return Err(3);
            }
            expected_frame += 1;
            let tail = rest[digits_len..].trim_start();
            let (_, symbol_tail) = tail.split_once(" in ").ok_or(3)?;
            let symbol = symbol_tail.split_whitespace().next().unwrap_or("");
            if symbol.is_empty() {
                return Err(3);
            }
            if !is_runtime_frame(symbol) {
                frames.push(fold_hex(symbol));
            }
        }
    }

    if kind.is_none() || expected_frame == 0 || !summary || frames.is_empty() {
        return Err(3);
    }
    Ok((kind.unwrap(), frames))
}

fn is_runtime_frame(s: &str) -> bool {
    s.starts_with("__asan") || s.starts_with("__interceptor") || s.starts_with("__hwasan")
}

fn fold_hex(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < bytes.len() {
        if i + 2 <= bytes.len() && bytes[i] == b'0' && bytes[i + 1] == b'x'
            && i + 2 < bytes.len() && bytes[i + 2].is_ascii_hexdigit()
        {
            out.push_str("<hex>");
            i += 2;
            while i < bytes.len() && bytes[i].is_ascii_hexdigit() {
                i += 1;
            }
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    out
}
