        let body = frames.join(" | ");
        let candidate = Rec { issue: 0, kind, frames: frames.clone(), body };
        match bag.get(&frames) {
            Some(old) if old.kind != candidate.kind => return Err(3),
            Some(_) => {}
            None => { bag.insert(frames, candidate); }
        }
    }
    if bag.is_empty() {
        return Err(3);
    }
    let mut records: Vec<Rec> = bag.into_values().collect();
    for (i, record) in records.iter_mut().enumerate() {
        record.issue = i as i32 + 1;
    }
    Ok(records)
}
